import { createHmac, timingSafeEqual } from 'node:crypto'
import { revalidatePath, revalidateTag } from 'next/cache'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const SEARCH_INDEX_URL =
  'https://raw.githubusercontent.com/gkzero0-cmyk/justserver3/main/public/notion-assets/search-index.json'

type NotionWebhookPayload = {
  verification_token?: string
  type?: string
  entity?: {
    id?: string
    type?: string
  }
  data?: unknown
  [key: string]: unknown
}

function verifySignature(body: string, signature: string | null) {
  const token = process.env.NOTION_WEBHOOK_VERIFICATION_TOKEN
  if (!token) return null
  if (!signature) return false

  const expected = `sha256=${createHmac('sha256', token)
    .update(body)
    .digest('hex')}`

  const expectedBuffer = Buffer.from(expected)
  const actualBuffer = Buffer.from(signature)

  if (expectedBuffer.length !== actualBuffer.length) return false
  return timingSafeEqual(expectedBuffer, actualBuffer)
}

async function triggerAssetSync() {
  const token = process.env.GITHUB_ACTIONS_TOKEN
  if (!token) return { triggered: false, reason: 'token-not-configured' }

  const response = await fetch(
    'https://api.github.com/repos/gkzero0-cmyk/justserver3/actions/workflows/sync-notion-assets.yml/dispatches',
    {
      method: 'POST',
      headers: {
        Accept: 'application/vnd.github+json',
        Authorization: `Bearer ${token}`,
        'X-GitHub-Api-Version': '2022-11-28',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ ref: 'main' }),
      cache: 'no-store'
    }
  )

  return {
    triggered: response.ok,
    status: response.status
  }
}

function normalizePageId(value?: string) {
  return value?.replaceAll('-', '') || null
}

async function searchIndexResponse() {
  const response = await fetch(SEARCH_INDEX_URL, {
    headers: {
      'Cache-Control': 'no-cache'
    },
    next: {
      revalidate: 60,
      tags: ['notion-search']
    }
  })

  if (!response.ok) {
    return Response.json(
      { pages: [], error: 'search-index-unavailable' },
      { status: 502 }
    )
  }

  return new Response(await response.text(), {
    status: 200,
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      'Cache-Control': 'public, s-maxage=60, stale-while-revalidate=300'
    }
  })
}

export async function GET(request: Request) {
  const url = new URL(request.url)

  if (url.searchParams.get('resource') === 'search-index') {
    return searchIndexResponse()
  }

  return Response.json({
    ready: true,
    endpoint: '/api/notion-webhook',
    signatureValidation:
      Boolean(process.env.NOTION_WEBHOOK_VERIFICATION_TOKEN),
    instantAssetSync: Boolean(process.env.GITHUB_ACTIONS_TOKEN),
    fallbackSyncMinutes: 5,
    liveContentCacheSeconds: 3600
  })
}

export async function POST(request: Request) {
  const rawBody = await request.text()

  let payload: NotionWebhookPayload
  try {
    payload = JSON.parse(rawBody) as NotionWebhookPayload
  } catch {
    return Response.json({ ok: false, error: 'invalid-json' }, { status: 400 })
  }

  if (payload.verification_token) {
    console.info(
      '[notion-webhook] verification-token',
      payload.verification_token
    )

    return Response.json({
      ok: true,
      verificationReceived: true
    })
  }

  const signature = request.headers.get('x-notion-signature')
  const verified = verifySignature(rawBody, signature)

  if (verified === null) {
    return Response.json(
      { ok: false, error: 'webhook-not-verified' },
      { status: 503 }
    )
  }

  if (!verified) {
    return Response.json(
      { ok: false, error: 'invalid-signature' },
      { status: 401 }
    )
  }

  const pageId = normalizePageId(payload.entity?.id)

  revalidateTag('notion-page', 'max')
  revalidateTag('notion-index', 'max')
  revalidateTag('notion-assets', 'max')
  revalidateTag('notion-search', 'max')
  revalidatePath('/')

  if (pageId) {
    revalidatePath(`/page/${pageId}`)
  }

  const assetSync = await triggerAssetSync().catch(() => ({
    triggered: false,
    reason: 'dispatch-failed'
  }))

  console.info('[notion-webhook] event', {
    type: payload.type || 'unknown',
    pageId,
    verified: true,
    assetSync
  })

  return Response.json({
    ok: true,
    revalidated: true,
    pageId,
    eventType: payload.type || null,
    assetSync
  })
}

'use client'

import Link from 'next/link'

export default function ErrorPage({
  reset
}: {
  reset: () => void
}) {
  return (
    <div className="state-page">
      <div className="state-card">
        <span className="state-icon" aria-hidden="true">!</span>
        <strong>일시적으로 문서를 불러오지 못했습니다.</strong>
        <p>잠시 후 다시 시도하거나 위키 홈에서 다른 문서를 확인해 주세요.</p>
        <div className="state-actions">
          <button type="button" onClick={() => reset()}>
            다시 시도
          </button>
          <Link href="/" prefetch={false}>위키 홈</Link>
        </div>
      </div>
    </div>
  )
}

* {
  box-sizing: border-box;
}

:root {
  --bg: #09090a;
  --panel: #121112;
  --panel-2: #191617;
  --line: #30292a;
  --text: #f6f1ec;
  --muted: #a99c96;
  --text-subtle: #a99a93;
  --text-faint: #93857f;
  --accent: #d95345;
  --accent-strong: #ef5b4d;
  --accent-soft: rgba(var(--accent-rgb),.12);
  --accent-rgb: 217,83,69;
  --gold: #d6a85f;
  --gold-soft: rgba(var(--gold-rgb),.12);
  --gold-rgb: 214,168,95;
  --success: #6fb983;
  --sidebar: 300px;
  --topbar: 76px;
  --content-max: 1240px;
  --border-soft: rgba(255,255,255,.06);
  --surface-soft: rgba(255,255,255,.018);
}

html {
  background: var(--bg);
  scroll-behavior: smooth;
}

body {
  margin: 0;
  color: var(--text);
  background:
    radial-gradient(circle at 70% -20%, rgba(var(--accent-rgb),.11), transparent 34rem),
    var(--bg);
  font-family: Pretendard, "Noto Sans KR", Inter, system-ui, sans-serif;
}

a {
  color: inherit;
}

button,
input {
  font: inherit;
}

.wiki-shell {
  min-height: 100vh;
}

.wiki-topbar {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 40;
  height: var(--topbar);
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 22px;
  border-bottom: 1px solid rgba(255,255,255,.08);
  background: rgba(10,13,18,.88);
  backdrop-filter: blur(18px);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid rgba(var(--accent-rgb),.34);
  border-radius: 10px;
  background: var(--accent-soft);
  color: var(--accent);
  font-weight: 900;
}

.brand > span:last-child {
  display: grid;
}

.brand strong {
  font-size: 14px;
}

.brand small {
  color: var(--muted);
  font-size: 10px;
  letter-spacing: .08em;
}

.top-actions {
  margin-left: auto;
}

.top-actions a {
  color: var(--muted);
  text-decoration: none;
  font-size: 13px;
}

.top-actions a:hover {
  color: var(--text);
}

.menu-button {
  display: none;
  border: 0;
  background: transparent;
  color: var(--text);
  font-size: 20px;
}

.wiki-sidebar {
  position: fixed;
  z-index: 30;
  top: var(--topbar);
  bottom: 0;
  left: 0;
  width: var(--sidebar);
  display: flex;
  flex-direction: column;
  padding: 24px 18px 16px;
  border-right: 1px solid rgba(255,255,255,.07);
  background: rgba(13,17,23,.9);
  backdrop-filter: blur(16px);
}

.sidebar-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 0 5px 14px;
}

.sidebar-head strong {
  font-size: 14px;
}

.sidebar-head span {
  color: var(--muted);
  font-size: 11px;
}

.wiki-search {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #0c1119;
  color: var(--muted);
}

.wiki-search:focus-within {
  border-color: rgba(var(--accent-rgb),.55);
  box-shadow: 0 0 0 3px rgba(var(--accent-rgb),.08);
}

.wiki-search input {
  min-width: 0;
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
}

.toc-list {
  flex: 1;
  overflow: auto;
  margin-top: 14px;
  padding-right: 4px;
}

.toc-item {
  display: block;
  width: 100%;
  padding: 8px 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #cbd5e1;
  text-align: left;
  cursor: pointer;
  line-height: 1.35;
  font-size: 13px;
}

.toc-item:hover {
  background: rgba(255,255,255,.05);
  color: var(--accent);
}

.toc-item.level-2 {
  padding-left: 18px;
  color: #aab6c7;
}

.toc-item.level-3 {
  padding-left: 28px;
  color: #8795a9;
  font-size: 12px;
}

.toc-empty {
  padding: 12px 8px;
  color: var(--muted);
  font-size: 12px;
}

.sidebar-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 6px 0;
  border-top: 1px solid rgba(255,255,255,.06);
  color: var(--muted);
  font-size: 11px;
}

.live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 12px rgba(var(--accent-rgb),.7);
}

.wiki-main {
  min-height: 100vh;
  padding: calc(var(--topbar) + 28px) 28px 72px calc(var(--sidebar) + 28px);
}

.document-card {
  width: min(100%, 1120px);
  margin: 0 auto;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 20px;
  background: rgba(17,22,31,.82);
  box-shadow: 0 24px 80px rgba(0,0,0,.26);
}

.notion {
  --fg-color: #e8edf4 !important;
  --fg-color-0: rgba(232,237,244,.09) !important;
  --fg-color-1: #cbd5e1 !important;
  --fg-color-2: #aeb9c8 !important;
  --fg-color-3: #7f8da2 !important;
  --bg-color: transparent !important;
  --bg-color-0: rgba(255,255,255,.03) !important;
  --bg-color-1: rgba(255,255,255,.06) !important;
}

.notion-page {
  width: 100% !important;
  padding: 38px clamp(20px, 5vw, 72px) 72px !important;
}

.notion-page-content {
  padding: 0 !important;
}

.notion-title {
  font-weight: 850 !important;
  letter-spacing: -.03em;
}

.notion-h1,
.notion-h2,
.notion-h3 {
  scroll-margin-top: calc(var(--topbar) + 24px);
}

.notion-callout {
  border: 1px solid rgba(var(--accent-rgb),.16) !important;
  border-radius: 14px !important;
}

.notion-collection-card {
  border: 1px solid rgba(255,255,255,.08) !important;
  border-radius: 14px !important;
  background: rgba(255,255,255,.025) !important;
}

.notion-table {
  border-radius: 12px;
  overflow: hidden;
}

.notion-link {
  text-decoration-color: rgba(var(--accent-rgb),.45) !important;
  text-underline-offset: 3px;
}

.state-page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: var(--bg);
}

.state-card {
  width: min(100%, 430px);
  padding: 32px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--panel);
  text-align: center;
}

.state-card p {
  color: var(--muted);
}

.state-card button {
  margin-top: 8px;
  padding: 10px 16px;
  border: 1px solid rgba(var(--accent-rgb),.35);
  border-radius: 10px;
  background: var(--accent-soft);
  color: var(--accent);
  cursor: pointer;
}

.spinner {
  display: inline-block;
  width: 26px;
  height: 26px;
  margin-bottom: 14px;
  border: 3px solid rgba(255,255,255,.12);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin .8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.sidebar-backdrop {
  display: none;
}

@media (max-width: 900px) {
  :root {
    --sidebar: 286px;
  }

  .menu-button {
    display: inline-grid;
    place-items: center;
    padding: 4px;
  }

  .wiki-sidebar {
    transform: translateX(-105%);
    transition: transform .22s ease;
    box-shadow: 20px 0 60px rgba(0,0,0,.35);
  }

  .wiki-sidebar.is-open {
    transform: translateX(0);
  }

  .sidebar-backdrop {
    position: fixed;
    z-index: 20;
    inset: var(--topbar) 0 0 0;
    display: block;
    border: 0;
    background: rgba(0,0,0,.5);
  }

  .wiki-main {
    padding: calc(var(--topbar) + 16px) 12px 48px;
  }

  .document-card {
    border-radius: 16px;
  }

  .notion-page {
    padding: 24px 18px 56px !important;
  }
}

@media (max-width: 520px) {
  .wiki-topbar {
    padding: 0 12px;
  }

  .brand small {
    display: none;
  }

  .top-actions a {
    font-size: 11px;
  }

  .notion-title {
    font-size: 32px !important;
  }
}


/* --- Wiki dashboard enhancements --- */
.brand {
  min-width: 0;
}

.brand > span:last-child {
  min-width: 0;
}

.brand strong {
  max-width: min(46vw, 520px);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}

.sync-chip,
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.sync-chip {
  padding: 6px 9px;
  border: 1px solid rgba(var(--accent-rgb),.18);
  border-radius: 999px;
  background: rgba(var(--accent-rgb),.06);
  color: var(--gold);
  font-size: 11px;
  white-space: nowrap;
}

.sidebar-home {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 12px;
  padding: 10px 11px;
  border: 1px solid rgba(255,255,255,.06);
  border-radius: 10px;
  background: rgba(255,255,255,.025);
  color: #dce5ef;
  text-decoration: none;
  font-size: 13px;
}

.sidebar-home:hover {
  border-color: rgba(var(--accent-rgb),.22);
  background: var(--accent-soft);
  color: var(--accent);
}

.toc-item {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  align-items: start;
  gap: 5px;
}

.toc-item > span:last-child {
  min-width: 0;
}

.wiki-main {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.wiki-hero {
  position: relative;
  width: min(100%, 1120px);
  margin: 0 auto;
  padding: clamp(24px, 4vw, 44px);
  overflow: hidden;
  border: 1px solid rgba(var(--accent-rgb),.13);
  border-radius: 22px;
  background:
    radial-gradient(circle at 85% 0%, rgba(var(--accent-rgb),.15), transparent 28rem),
    linear-gradient(135deg, rgba(18,25,34,.98), rgba(12,16,23,.96));
  box-shadow: 0 22px 70px rgba(0,0,0,.24);
}

.wiki-hero::after {
  content: "";
  position: absolute;
  width: 260px;
  height: 260px;
  right: -95px;
  bottom: -145px;
  border: 1px solid rgba(var(--accent-rgb),.14);
  border-radius: 50%;
  box-shadow:
    0 0 0 28px rgba(var(--accent-rgb),.025),
    0 0 0 56px rgba(var(--accent-rgb),.018);
  pointer-events: none;
}

.hero-badges {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
}

.hero-badge {
  min-height: 28px;
  padding: 5px 10px;
  border: 1px solid rgba(255,255,255,.075);
  border-radius: 999px;
  background: rgba(255,255,255,.035);
  color: #aeb9c8;
  font-size: 11px;
}

.hero-badge.primary {
  border-color: rgba(var(--accent-rgb),.22);
  background: rgba(var(--accent-rgb),.08);
  color: #d9ffc1;
}

.hero-copy {
  position: relative;
  z-index: 1;
  max-width: 770px;
}

.hero-kicker {
  margin: 0 0 7px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .16em;
}

.hero-copy h1 {
  margin: 0;
  font-size: clamp(30px, 5vw, 52px);
  line-height: 1.04;
  letter-spacing: -.045em;
}

.hero-copy > p:last-child {
  max-width: 680px;
  margin: 16px 0 0;
  color: #aeb9c8;
  line-height: 1.75;
  font-size: 14px;
}

.quick-nav {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 30px;
}

.quick-nav-card {
  display: grid;
  grid-template-columns: 34px minmax(0,1fr) 18px;
  align-items: center;
  gap: 8px;
  min-height: 58px;
  padding: 10px 12px;
  border: 1px solid rgba(255,255,255,.075);
  border-radius: 13px;
  background: rgba(255,255,255,.025);
  color: #e5ebf3;
  text-align: left;
  cursor: pointer;
  transition:
    transform .18s ease,
    border-color .18s ease,
    background .18s ease;
}

.quick-nav-card:hover {
  transform: translateY(-2px);
  border-color: rgba(var(--accent-rgb),.3);
  background: rgba(var(--accent-rgb),.07);
}

.quick-nav-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: rgba(255,255,255,.045);
  font-size: 17px;
}

.quick-nav-label {
  min-width: 0;
  overflow: hidden;
  color: #dbe4ee;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 700;
}

.quick-nav-arrow {
  color: #627083;
  font-size: 14px;
  transition: transform .18s ease, color .18s ease;
}

.quick-nav-card:hover .quick-nav-arrow {
  transform: translateX(2px);
  color: var(--accent);
}

.document-card {
  position: relative;
}

.document-card::before {
  content: "GUIDE";
  position: absolute;
  z-index: 2;
  top: 14px;
  right: 16px;
  padding: 4px 7px;
  border-radius: 6px;
  background: rgba(var(--accent-rgb),.075);
  color: rgba(200,247,172,.65);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .12em;
  pointer-events: none;
}

.notion-page-content {
  max-width: 920px !important;
  margin: 0 auto !important;
}

.notion-h1 {
  margin-top: 2.3em !important;
  padding-bottom: 10px;
  border-bottom: 1px solid rgba(255,255,255,.08);
}

.notion-h2 {
  margin-top: 2em !important;
}

.notion-callout {
  padding: 14px 16px !important;
  background: rgba(var(--accent-rgb),.035) !important;
}

.notion-collection-card {
  overflow: hidden;
  transition:
    transform .18s ease,
    border-color .18s ease,
    background .18s ease;
}

.notion-collection-card:hover {
  transform: translateY(-2px);
  border-color: rgba(var(--accent-rgb),.24) !important;
  background: rgba(var(--accent-rgb),.035) !important;
}

.notion-collection-card-cover {
  background: #0d1118 !important;
}

.notion-collection-card img,
.notion-asset-wrapper img,
.notion-image {
  border-radius: 12px !important;
}

.notion-simple-table,
.notion-table {
  border: 1px solid rgba(255,255,255,.08) !important;
  border-radius: 12px;
}

.notion-simple-table th,
.notion-simple-table td,
.notion-table th,
.notion-table td {
  border-color: rgba(255,255,255,.07) !important;
}

.notion-toggle {
  margin: 7px 0 !important;
  padding: 8px 10px;
  border-radius: 9px;
}

.notion-toggle:hover {
  background: rgba(255,255,255,.025);
}

.notion-bookmark {
  overflow: hidden;
  border-color: rgba(255,255,255,.08) !important;
  border-radius: 12px !important;
}

.notion-bookmark:hover {
  border-color: rgba(var(--accent-rgb),.24) !important;
}

.wiki-footer {
  width: min(100%, 1120px);
  margin: 0 auto;
  padding: 20px 4px 6px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  color: #718096;
  font-size: 11px;
}

.wiki-footer > div {
  display: grid;
  gap: 3px;
}

.wiki-footer strong {
  color: #aeb9c8;
  font-size: 12px;
}

.wiki-footer a {
  color: #94a3b8;
  text-decoration: none;
}

.wiki-footer a:hover {
  color: var(--accent);
}

@media (max-width: 900px) {
  .sync-chip {
    display: none;
  }

  .quick-nav {
