.wiki-directory {
  width: min(100%, 1120px);
  margin: 0 auto;
  padding: 20px;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 18px;
  background: rgba(15,20,28,.78);
  box-shadow: 0 18px 54px rgba(0,0,0,.18);
}

.directory-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 16px;
}

.directory-heading p {
  margin: 0 0 4px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .14em;
}

.directory-heading h2 {
  margin: 0;
  font-size: 19px;
  letter-spacing: -.02em;
}

.directory-heading > span {
  color: var(--muted);
  font-size: 11px;
  white-space: nowrap;
}

.directory-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.directory-card {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) 18px;
  align-items: center;
  gap: 10px;
  min-height: 68px;
  padding: 12px;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 13px;
  background: rgba(255,255,255,.024);
  color: inherit;
  text-decoration: none;
  transition:
    transform .18s ease,
    border-color .18s ease,
    background .18s ease;
}

.directory-card:hover {
  transform: translateY(-2px);
  border-color: rgba(var(--accent-rgb),.26);
  background: rgba(var(--accent-rgb),.05);
}

.directory-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: rgba(255,255,255,.045);
  font-size: 19px;
}

.directory-copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.directory-copy strong {
