}

.directory-group-head {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.directory-group-head > span {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: rgba(var(--accent-rgb),.07);
  font-size: 17px;
}

.directory-group-head > div {
  display: grid;
  gap: 2px;
}

.directory-group-head strong {
  color: #e4ebf4;
  font-size: 13px;
}

.directory-group-head small {
  color: #718096;
  font-size: 10px;
}

.directory-group-head em {
  display: grid;
  place-items: center;
  min-width: 26px;
  height: 24px;
  padding: 0 7px;
  border: 1px solid rgba(255,255,255,.07);
