  box-shadow: 0 18px 54px rgba(0,0,0,.16);
}

.starter-guide-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 16px;
}

.starter-guide-head p {
  margin: 0 0 4px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .15em;
}

.starter-guide-head h2 {
  margin: 0;
  font-size: 22px;
  letter-spacing: -.03em;
}

.starter-guide-head span {
  display: block;
  margin-top: 6px;
  color: #8391a5;
  font-size: 12px;
}

.starter-guide-head > strong {
  padding: 6px 9px;
  border: 1px solid rgba(var(--accent-rgb),.18);
  border-radius: 999px;
  background: rgba(var(--accent-rgb),.06);
