/* === Reader UX pass 2026-09-25 === */
.directory-group {
  scroll-margin-top: calc(var(--topbar) + 20px);
}

.search-result-meta-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.search-draft-badge {
  padding: 2px 6px;
  border: 1px dashed rgba(160,147,140,.22);
  border-radius: 999px;
  color: #a99a93;
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
}

.document-card .notion-table,
.document-card .notion-simple-table {
  max-width: 100%;
  overflow-x: auto !important;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(var(--gold-rgb),.28) transparent;
}

.document-card .notion-table::-webkit-scrollbar,
.document-card .notion-simple-table::-webkit-scrollbar {
  height: 6px;
}

.document-card .notion-table::-webkit-scrollbar-thumb,
.document-card .notion-simple-table::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.25);
}

.mobile-reading-tools {
  display: none;
}

.state-card {
  display: grid;
  justify-items: center;
  gap: 10px;
}

.state-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(var(--accent-rgb),.24);
  border-radius: 50%;
  background: rgba(var(--accent-rgb),.08);
  color: #e48378;
  font-weight: 900;
}

.state-actions {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}

.state-actions a,
.state-actions button {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 15px;
  border-radius: 10px;
  text-decoration: none;
  cursor: pointer;
}

.state-actions a {
  border: 1px solid rgba(var(--gold-rgb),.18);
  background: rgba(var(--gold-rgb),.055);
  color: #cbb189;
}

.loading-wiki-shell {
  min-height: 100vh;
  background: var(--bg);
  color: var(--text);
}

.loading-topbar {
  position: fixed;
  z-index: 40;
  inset: 0 0 auto 0;
  height: var(--topbar);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 22px;
  border-bottom: 1px solid rgba(255,255,255,.06);
  background: rgba(9,9,10,.96);
}

.loading-logo,
.loading-line,
.loading-search,
.loading-nav-item,
.loading-block {
  display: block;
  overflow: hidden;
  background: rgba(255,255,255,.055);
  position: relative;
}

.loading-logo::after,
.loading-line::after,
.loading-search::after,
.loading-nav-item::after,
.loading-block::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.06), transparent);
  animation: wikiSkeleton 1.5s ease-in-out infinite;
}

.loading-logo {
  width: 46px;
  height: 46px;
  border-radius: 12px;
}

.loading-line {
  height: 11px;
  border-radius: 999px;
}

.loading-line.is-brand { width: 190px; }
.loading-line.is-title { width: 92px; margin-bottom: 14px; }
.loading-line.is-kicker { width: 120px; }
.loading-line.is-heading { width: min(65%, 520px); height: 36px; }
.loading-line.is-wide { width: 92%; }
.loading-line.is-medium { width: 64%; }

.loading-search {
  width: 220px;
  height: 38px;
  margin-left: auto;
  border-radius: 11px;
}

.loading-sidebar {
  position: fixed;
  top: var(--topbar);
  bottom: 0;
  left: 0;
  width: var(--sidebar);
  padding: 25px 20px;
  border-right: 1px solid rgba(255,255,255,.05);
  background: rgba(13,11,12,.96);
}

.loading-nav-item {
  width: 100%;
  height: 38px;
  margin: 6px 0;
  border-radius: 9px;
}

.loading-main {
  min-height: 100vh;
  padding: calc(var(--topbar) + 28px) 32px 72px calc(var(--sidebar) + 32px);
  display: grid;
  align-content: start;
  gap: 20px;
}

.loading-hero,
.loading-document {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  display: grid;
  gap: 16px;
  border: 1px solid rgba(255,255,255,.055);
  background: rgba(255,255,255,.018);
}

.loading-hero {
  min-height: 138px;
  align-content: center;
  padding: 26px;
  border-radius: 20px;
}

.loading-document {
  min-height: 360px;
  align-content: start;
  padding: 34px;
  border-radius: 18px;
}

.loading-block {
  width: 100%;
  height: 150px;
  margin-top: 8px;
  border-radius: 14px;
}

@keyframes wikiSkeleton {
  100% { transform: translateX(100%); }
}

